def _transfer_existing_data():
    bind = op.get_bind()
    meta = sa.MetaData()
    meta.reflect(bind=bind)
    def insert(table, **values):
        bind.execute(meta.tables[table].insert().values(**values))
    categories = [
        ("Nature", "Природа", "Nature", "Табиғат"), ("Culture", "Культура", "Culture", "Мәдениет"),
        ("Adventure", "Приключения", "Adventure", "Шытырман"), ("Food", "Гастрономия", "Food", "Гастрономия"),
        ("Beach", "Пляж", "Beach", "Жағажай"), ("City", "Город", "City", "Қала"),
    ]
    for code, ru, en, kk in categories:
        insert("categories", code=code, name_ru=ru, name_en=en, name_kk=kk)
    for row in bind.execute(sa.select(meta.tables["destinations"])).mappings().all():
        for language in ("ru", "en", "kk"):
            suffix = "" if language == "ru" else "_" + language
            insert("destination_translations", destination_id=row["id"], language=language,
                   **{field: row[field + suffix] or "" for field in ("name", "country", "description")})
    now = datetime.now(timezone.utc)
    for row in bind.execute(sa.select(meta.tables["experiences"])).mappings().all():
        days = {}
        for language in ("ru", "en", "kk"):
            suffix = "" if language == "ru" else "_" + language
            insert("experience_translations", experience_id=row["id"], language=language,
                   title=row["title" + suffix] or "", description=row["description" + suffix] or "")
            for kind in ("tags", "included", "excluded"):
                values = row[kind + suffix] or []
                if isinstance(values, str):
                    values = json.loads(values)
                for position, value in enumerate(values):
                    insert("catalog_lines", experience_id=row["id"], language=language, kind=kind, position=position, text=value)
            itinerary = row["itinerary" + suffix] or []
            if isinstance(itinerary, str):
                itinerary = json.loads(itinerary)
            for value in itinerary:
                day = int(value["day"])
                if day not in days:
                    days[day] = str(uuid4())
                    insert("itinerary_days", id=days[day], experience_id=row["id"], day=day)
                insert("itinerary_translations", day_id=days[day], language=language, title=value["title"], description=value["description"])
        insert("experience_images", id=str(uuid4()), experience_id=row["id"], position=0, url=row["image_url"], alt=row["title"])
        if row["currency"] == "USD":
            insert("currency_conversion_records", id=str(uuid4()), experience_id=row["id"], original_amount=row["price_from"],
                   original_currency="USD", equivalent_amount=row["price_from"] * Decimal(500), factor=Decimal(500),
                   rule="Educational USD × 500; not an exchange rate", created_at=now)
            bind.execute(sa.text("UPDATE departures SET price = price * 500 WHERE experience_id = :id"), {"id": row["id"]})
            bind.execute(sa.text("UPDATE experiences SET price_from = price_from * 500, currency = 'KZT' WHERE id = :id"), {"id": row["id"]})
    # Do not infer any historical payment from a legacy booking status.
    for row in bind.execute(sa.select(meta.tables["bookings"])).mappings().all():
        insert("booking_items", id=str(uuid4()), booking_id=row["id"], kind="tour", name="Historical booking price", quantity=row["travelers_count"],
               unit_amount=(row["total_amount"] / row["travelers_count"]).quantize(Decimal("0.01")), total_amount=row["total_amount"], currency=row["currency"])
        for position in range(row["travelers_count"]):
            insert("booking_participants", id=str(uuid4()), booking_id=row["id"], position=position,
                   name=row["contact_name"] if position == 0 else "Участник " + str(position + 1))
        bind.execute(sa.text("UPDATE bookings SET subtotal_amount = total_amount, expires_at = CASE WHEN status = 'pending' THEN :now ELSE NULL END WHERE id = :id"), {"now": now, "id": row["id"]})
        if row["currency"] == "USD":
            insert("currency_conversion_records", id=str(uuid4()), booking_id=row["id"], original_amount=row["total_amount"],
                   original_currency="USD", equivalent_amount=row["total_amount"] * Decimal(500), factor=Decimal(500),
                   rule="Historical equivalent only; original financial fact retained", created_at=now)
